package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.executing.*;import com.intermarche.backoffice.domain.order.*;import com.intermarche.backoffice.domain.store.*;import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import io.restassured.response.Response;import org.junit.jupiter.api.Test;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(ParcelWorkflowTest.class)
class ParcelWorkflowTest extends TraceabilityWorkflowTest {
 Long customer;Stock physical;
 Response parcel(String actor,String path,Object body){return given().auth().oauth2(actor).contentType("application/json").body(body).post("/parcels"+path);}
 Map<String,Object> prepared(){line();physical=stock();pick(physical);customer=QuarkusTransaction.requiringNew().call(()->{var lot=em.createQuery("select lot from Lot lot join lot.lines l where l.id=?1",com.intermarche.backoffice.domain.wms.Lot.class).setParameter(1,PickedItem.<PickedItem>findById(f.item()).lotLine.id).getSingleResult();lot.fulfillment.chunks.add(lot.chunk);em.flush();return lot.fulfillment.order.id;});return parcel(f.picker(),"",Map.of("storeId",f.store(),"orderId",customer,"requestKey",key())).then().statusCode(200).extract().jsonPath().getMap("$");}
 long packagingType(){Long existing=QuarkusTransaction.requiringNew().call(()->{var t=com.intermarche.backoffice.domain.fieldops.SupportType.<com.intermarche.backoffice.domain.fieldops.SupportType>find("store.id=?1 and code='PARCEL_TEST'",f.store()).firstResult();return t==null?null:t.id;});if(existing!=null)return existing;long id=call(f.manager(),"PUT","/support-types",Map.of("storeId",f.store(),"code","PARCEL_TEST","label","Carton test","kind","CARTON","allowedZones","AMBIENT","maxVolumeLiters",60)).then().statusCode(200).extract().jsonPath().getLong("id");call(f.manager(),"POST","/consumables/receive",Map.of("storeId",f.store(),"typeId",id,"quantity",100,"reason","Stock de test","requestKey",key())).then().statusCode(200);return id;}
 Map<String,Object> input(Map<String,Object> p){return new LinkedHashMap<>(Map.of("consumableTypeId",packagingType(),"storeId",f.store(),"parcelId",p.get("id"),"expectedRevision",p.get("revision"),"requestKey",key()));}
 Map<String,Object> save(Map<String,Object> p,Object qty){var i=input(p);i.put("packagingType","CARTON");i.put("contents",List.of(Map.of("itemId",f.item(),"quantity",qty)));i.put("weightKg",1.25);return parcel(f.picker(),"/content",i).then().statusCode(200).extract().jsonPath().getMap("$");}
 @Test void allocatingTwoParcelsCannotDuplicatePhysicalContentAndClosureIsControlled(){var p=prepared();var emptyClose=input(p);emptyClose.put("contentsConfirmed",true);parcel(f.picker(),"/close",emptyClose).then().statusCode(400);p=save(p,1);var second=parcel(f.picker(),"",Map.of("storeId",f.store(),"orderId",customer,"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");var overflow=input(second);overflow.put("packagingType","CARTON");overflow.put("contents",List.of(Map.of("itemId",f.item(),"quantity",2)));parcel(f.picker(),"/content",overflow).then().statusCode(400);save(second,1);var close=input(p);parcel(f.picker(),"/close",close).then().statusCode(400);close.put("contentsConfirmed",true);close.put("requestKey",key());p=parcel(f.picker(),"/close",close).then().statusCode(200).body("state",org.hamcrest.Matchers.is("CLOSED")).extract().jsonPath().getMap("$");parcel(f.picker(),"/close",close).then().statusCode(200);var change=input(p);change.put("packagingType","CARTON");change.put("contents",List.of());parcel(f.picker(),"/content",change).then().statusCode(409);var reopen=input(p);reopen.put("reason","Correction du contrôle après erreur de saisie");parcel(f.picker(),"/reopen",reopen).then().statusCode(403);parcel(f.manager(),"/reopen",reopen).then().statusCode(200).body("state",org.hamcrest.Matchers.is("OPEN"));QuarkusTransaction.requiringNew().run(()->eq(20,stocks.availability(physical.account(),null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical));}
 @Test void closedParcelPreventsMovingItsGoodsUntilAuthorizedReopening(){var p=save(prepared(),2);var close=input(p);close.put("contentsConfirmed",true);p=parcel(f.picker(),"/close",close).then().statusCode(200).extract().jsonPath().getMap("$");attach(f.second());var move=command("MOVE_ITEM");move.putAll(Map.of("itemId",f.item(),"toteCode",f.tote(),"targetToteCode",f.second()));command(move).then().statusCode(409);QuarkusTransaction.requiringNew().run(()->assertEquals(f.tote(),PickedItem.<PickedItem>findById(f.item()).loadedTote.tote.code));var reopen=input(p);reopen.put("reason","Déplacer le contenu vers un nouveau bac");parcel(f.manager(),"/reopen",reopen).then().statusCode(200);move.put("requestKey",key());command(move).then().statusCode(200);}
 @Test void recallBetweenConstitutionAndClosureBlocksTheColis(){var p=save(prepared(),2);quality(f.manager(),"POST","/cases",Map.of("storeId",f.store(),"productId",f.product(),"lotId",physical.second(),"kind","RECALL","reason","Rappel avant départ","requestKey",key(),"includeUnknownLots",true)).then().statusCode(200);var close=input(p);close.put("contentsConfirmed",true);parcel(f.picker(),"/close",close).then().statusCode(409);}
 @Test void configuredDimensionsAndScanAreRequiredButDisabledChecksAreNotInvented(){var p=save(prepared(),2);var policy=Map.of("storeId",f.store(),"requestKey",key(),"expectedRevision",0,"requireWeight",false,"requireDimensions",true,"requireContentConfirmation",false,"requireScan",true);parcel(f.picker(),"/policy",policy).then().statusCode(403);parcel(f.manager(),"/policy",policy).then().statusCode(200);var close=input(p);parcel(f.picker(),"/close",close).then().statusCode(400);var dims=input(p);dims.putAll(Map.of("packagingType","CARTON","contents",List.of(Map.of("itemId",f.item(),"quantity",2)),"lengthCm",10,"widthCm",20,"heightCm",30));p=parcel(f.picker(),"/content",dims).then().statusCode(200).extract().jsonPath().getMap("$");close=input(p);close.put("scannedCode",p.get("code"));parcel(f.picker(),"/close",close).then().statusCode(200);}
 @Test void unitFractionsAndForeignStoreCannotBeAssigned(){var p=prepared();var bad=input(p);bad.put("packagingType","CARTON");bad.put("contents",List.of(Map.of("itemId",f.item(),"quantity",0.5)));parcel(f.picker(),"/content",bad).then().statusCode(400);given().auth().oauth2(f.picker()).get("/parcels/"+p.get("id")+"?storeId="+f.other()).then().statusCode(403);}
 @jakarta.inject.Inject com.intermarche.backoffice.engine.stock.StockTraceLedger traceLedger;
 @Test void twoManufacturerLotsAreDistributedAcrossParcelsWithoutClaimingTheSameLotTwice(){line();physical=stock();QuarkusTransaction.requiringNew().run(()->traceLedger.entry(com.intermarche.backoffice.domain.stock.StockSegment.findById(physical.firstSegment()),new BigDecimal("-9"),"prepare-two-lots-"+key(),"out","TEST_ISSUE",com.intermarche.backoffice.domain.util.DateTimeProvider.now()));attach(f.tote());var pick=command("PICK");pick.putAll(Map.of("itemId",f.item(),"quantity",2,"toteCode",f.tote()));command(pick).then().statusCode(200);customer=QuarkusTransaction.requiringNew().call(()->{var lot=em.createQuery("select lot from Lot lot join lot.lines l where l.id=?1",com.intermarche.backoffice.domain.wms.Lot.class).setParameter(1,PickedItem.<PickedItem>findById(f.item()).lotLine.id).getSingleResult();lot.fulfillment.chunks.add(lot.chunk);return lot.fulfillment.order.id;});var a=parcel(f.picker(),"",Map.of("storeId",f.store(),"orderId",customer,"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");a=save(a,1);var b=parcel(f.picker(),"",Map.of("storeId",f.store(),"orderId",customer,"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");b=save(b,1);var first=(List<Map<String,Object>>)((List<Map<String,Object>>)a.get("contents")).getFirst().get("trace");var second=(List<Map<String,Object>>)((List<Map<String,Object>>)b.get("contents")).getFirst().get("trace");assertEquals(1,first.size());assertEquals(1,second.size());assertNotEquals(first.getFirst().get("allocationId"),second.getFirst().get("allocationId"));assertEquals(0,BigDecimal.ONE.compareTo(new BigDecimal(first.getFirst().get("quantity").toString())));for(var p:List.of(a,b)){var close=input(p);close.put("contentsConfirmed",true);parcel(f.picker(),"/close",close).then().statusCode(200);}}

 @jakarta.inject.Inject com.intermarche.backoffice.engine.stock.PickedStockCoordinator custody;
 @Test void oneParcelCanContainGoodsFromTwoDistinctSourceTotesWithoutChangingStock(){var p=prepared();attach(f.second());long otherId=QuarkusTransaction.requiringNew().call(()->{var item=PickedItem.<PickedItem>findById(f.item());item.quantity=BigDecimal.ONE;var other=new PickedItem();other.product=item.product;other.lotLine=item.lotLine;other.sourceLocation=item.sourceLocation;other.quantity=BigDecimal.ONE;other.status=PickedItem.PickStatus.PICKED;other.loadedTote=LoadedTote.find("tote.code=?1 and status=?2",f.second(),LoadedTote.Status.IN_USE).firstResult();other.persist();var execution=com.intermarche.backoffice.client.PickingExecution.<com.intermarche.backoffice.client.PickingExecution>findById(f.execution());execution.itemsToPick.add(other);em.flush();custody.syncLines(com.intermarche.backoffice.domain.store.Store.findById(f.store()),List.of(item.lotLine.id),null,"two-source-totes-"+key());return other.id;});var save=input(p);save.put("packagingType","CARTON");save.put("weightKg",1.2);save.put("contents",List.of(Map.of("itemId",f.item(),"quantity",1),Map.of("itemId",otherId,"quantity",1)));p=parcel(f.picker(),"/content",save).then().statusCode(200).extract().jsonPath().getMap("$");var contents=(List<Map<String,Object>>)p.get("contents");assertEquals(2,contents.size());assertEquals(2,contents.stream().map(c->c.get("toteCode")).distinct().count());var close=input(p);close.put("contentsConfirmed",true);parcel(f.picker(),"/close",close).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->eq(20,stocks.availability(physical.account(),null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical));}

 @Test void cartonIsConsumedOnceEvenWhenTheParcelIsReopened(){
  var p=save(prepared(),2);long type=packagingType();var close=input(p);close.put("contentsConfirmed",true);var closed=parcel(f.picker(),"/close",close).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");parcel(f.picker(),"/close",close).then().statusCode(200);
  var reopen=input(closed);reopen.put("reason","Vérification sans changer l’emballage");var reopened=parcel(f.manager(),"/reopen",reopen).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");close=input(reopened);close.put("contentsConfirmed",true);parcel(f.picker(),"/close",close).then().statusCode(200);
  QuarkusTransaction.requiringNew().run(()->{assertEquals(99,com.intermarche.backoffice.domain.fieldops.SupportType.<com.intermarche.backoffice.domain.fieldops.SupportType>findById(type).stockQuantity);assertEquals(2,com.intermarche.backoffice.domain.fieldops.PackagingMovement.count("type.id",type));});
 }
 @Test void retainsTheSourceCartonWithoutConsumingAnotherOne(){
  var p=prepared();long type=packagingType();String code="SRC-"+f.store();call(f.manager(),"PUT","/supports",Map.of("storeId",f.store(),"typeId",type,"code",code)).then().statusCode(200);attach(code);
  var move=command("MOVE_ITEM");move.putAll(Map.of("itemId",f.item(),"toteCode",f.tote(),"targetToteCode",code));command(move).then().statusCode(200);
  p=save(p,2);var close=input(p);close.put("contentsConfirmed",true);parcel(f.picker(),"/close",close).then().statusCode(200).body("packagingSupportCode",org.hamcrest.Matchers.is(code));
  QuarkusTransaction.requiringNew().run(()->assertEquals(99,com.intermarche.backoffice.domain.fieldops.SupportType.<com.intermarche.backoffice.domain.fieldops.SupportType>findById(type).stockQuantity));
 }
 @Test void shortageAtClosureLeavesTheParcelOpen(){
  var p=save(prepared(),2);long type=packagingType();call(f.manager(),"POST","/consumables/adjust",Map.of("storeId",f.store(),"typeId",type,"quantity",-100,"reason","Stock épuisé","requestKey",key())).then().statusCode(200);var close=input(p);close.put("contentsConfirmed",true);parcel(f.picker(),"/close",close).then().statusCode(400);
  long parcelId=((Number)p.get("id")).longValue();QuarkusTransaction.requiringNew().run(()->{assertEquals("OPEN",Parcel.<Parcel>findById(parcelId).state);assertNull(Parcel.<Parcel>findById(parcelId).packagingSupport);assertEquals(0,com.intermarche.backoffice.domain.fieldops.PhysicalSupport.count("code","PKG-"+parcelId));});
 }
 @Test void packagingEntryPreselectsPalletAndConsumesOnlyOnClosure(){
  prepared();long type=call(f.manager(),"PUT","/support-types",Map.of("storeId",f.store(),"code","PALLET_ENTRY","label","Palette","kind","PALLET","allowedZones","AMBIENT","maxVolumeLiters",1200)).then().statusCode(200).extract().jsonPath().getLong("id");
  call(f.manager(),"POST","/consumables/receive",Map.of("storeId",f.store(),"typeId",type,"quantity",1,"reason","Livraison","requestKey",key())).then().statusCode(200);
  var p=parcel(f.picker(),"",Map.of("storeId",f.store(),"orderId",customer,"consumableTypeId",type,"requestKey",key())).then().statusCode(200).body("packagingType",org.hamcrest.Matchers.is("PALLET")).extract().jsonPath().<String,Object>getMap("$");
  QuarkusTransaction.requiringNew().run(()->assertEquals(1,com.intermarche.backoffice.domain.fieldops.SupportType.<com.intermarche.backoffice.domain.fieldops.SupportType>findById(type).stockQuantity));
  var content=input(p);content.putAll(Map.of("packagingType","PALLET","contents",List.of(Map.of("itemId",f.item(),"quantity",2)),"weightKg",2));p=parcel(f.picker(),"/content",content).then().statusCode(200).extract().jsonPath().getMap("$");var close=input(p);close.putAll(Map.of("consumableTypeId",type,"contentsConfirmed",true));parcel(f.picker(),"/close",close).then().statusCode(200);
  QuarkusTransaction.requiringNew().run(()->assertEquals(0,com.intermarche.backoffice.domain.fieldops.SupportType.<com.intermarche.backoffice.domain.fieldops.SupportType>findById(type).stockQuantity));
 }
 @Test void reopenTargetIsValidatedWithoutChangingTheParcelOrStock(){
  var p=save(prepared(),2);var close=input(p);close.put("contentsConfirmed",true);p=parcel(f.picker(),"/close",close).then().statusCode(200).extract().jsonPath().getMap("$");
  long id=((Number)p.get("id")).longValue();Object revision=p.get("revision");String path="/parcels/"+id+"/reopen-target?storeId="+f.store()+"&code=";
  given().auth().oauth2(f.picker()).get(path+f.tote()).then().statusCode(403);
  given().auth().oauth2(f.manager()).get(path+"INCONNU").then().statusCode(400);
  long target=given().auth().oauth2(f.manager()).get(path+f.tote()).then().statusCode(200).body("compatible",org.hamcrest.Matchers.is(true)).body("code",org.hamcrest.Matchers.is(f.tote())).extract().jsonPath().getLong("id");
  QuarkusTransaction.requiringNew().run(()->LoadedTote.<LoadedTote>findById(target).storageType=TemperatureZone.CHILLED);
  given().auth().oauth2(f.manager()).get(path+f.tote()).then().statusCode(400);
  QuarkusTransaction.requiringNew().run(()->{var t=LoadedTote.<LoadedTote>findById(target);t.storageType=TemperatureZone.AMBIENT;t.status=LoadedTote.Status.DELIVERED;});
  given().auth().oauth2(f.manager()).get(path+f.tote()).then().statusCode(400);
  QuarkusTransaction.requiringNew().run(()->LoadedTote.<LoadedTote>findById(target).status=LoadedTote.Status.IN_USE);
  given().auth().oauth2(f.manager()).get("/parcels/"+id+"?storeId="+f.store()).then().statusCode(200).body("state",org.hamcrest.Matchers.is("CLOSED")).body("revision",org.hamcrest.Matchers.is(((Number)revision).intValue()));
  QuarkusTransaction.requiringNew().run(()->eq(20,stocks.availability(physical.account(),null,com.intermarche.backoffice.domain.util.DateTimeProvider.now()).physical));
 }
}
